    return MaterialApp(
      title: "Halal",
      home: HomeScreen(),
    );
  }
}

class HomeScreen extends StatefulWidget {
  @override
  _HomeScreenState createState() => _HomeScreenState();
}

class _HomeScreenState extends State<HomeScreen> {
  bool _toggleSwitch = false;

  void _updateToggle() {
    setState(() {
      _toggleSwitch = !_toggleSwitch;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Halal Info')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: <Widget>[
            ElevatedButton(
              onPressed: () {
                if (_toggleSwitch) {
                  print("Toggle Switch ON");
                } else {
                  print("Toggle Switch OFF");
                }
              },
              child: Text(_toggleSwitch ? 'ON' : 'OFF'),
            ),
            SizedBox(height: 20),
            ElevatedButton(
              onPressed: () {
                // Do something with the toggle switch
                print("Press the Button!");
              },
              child: Text("Press Me"),
            )
          ],
        ),
      ),
    );
  }
}
